        # 身份证校验位错误
        self.assertEqual(value_categories("110101199003078878"), set())
        # 银行卡 Luhn 校验失败
        self.assertEqual(value_categories("6222020200112233446"), set())
        self.assertEqual(value_categories("not-an-email@"), set())

